# /etc/nginx/conf.d/app.conf
upstream app_backend {
    server 10.0.0.11:3000;
    server 10.0.0.12:3000;
    server 10.0.0.13:3000;
}

server {
    listen 443 ssl;
    server_name api.contoh.id;

    location / {
        proxy_pass http://app_backend;
        proxy_http_version 1.1;
        proxy_set_header Connection "";
    }
}

# least_conn: terbaik untuk API dengan durasi request bervariasi
upstream app_backend {
    least_conn;
    server 10.0.0.11:3000;
    server 10.0.0.12:3000;
    server 10.0.0.13:3000;
    keepalive 32;
}

# ip_hash: session menempel di satu server
upstream legacy_app {
    ip_hash;
    server 10.0.0.21:8080;
    server 10.0.0.22:8080;
}

# hash konsisten: URL yang sama selalu ke server yang sama
upstream cache_nodes {
    hash $request_uri consistent;
    server 10.0.0.31:8000;
    server 10.0.0.32:8000;
}

# /etc/nginx/conf.d/app.conf
upstream app_backend {
    least_conn;
    # Server baru (8 core) dapat beban 3x lipat dari server lama (4 core)
    server 10.0.0.11:3000 weight=3 max_fails=3 fail_timeout=30s;
    server 10.0.0.12:3000 weight=1 max_fails=3 fail_timeout=30s;
    # Server cadangan: hanya dipakai kalau semua server utama down
    server 10.0.0.13:3000 backup;
    # Server dalam maintenance: jangan kirim traffic sama sekali
    # server 10.0.0.14:3000 down;
    keepalive 32;
}

# /etc/nginx/conf.d/app.conf
upstream app_backend {
    least_conn;
    server 10.0.0.11:3000;
    server 10.0.0.12:3000;
    keepalive 32;
    keepalive_timeout 60s;
    keepalive_requests 10000;
}

server {
    location / {
        proxy_pass http://app_backend;
        proxy_http_version 1.1;
        proxy_set_header Connection "";
        proxy_next_upstream error timeout http_502 http_503;
        proxy_next_upstream_tries 3;
    }
}

# Sticky berdasarkan cookie session aplikasi (NGINX open source)
upstream app_backend {
    hash $cookie_sessionid consistent;
    server 10.0.0.11:3000;
    server 10.0.0.12:3000;
}

